        recs=[json.loads(l) for l in open(p)]
        acc=sum(r['correct'] for r in recs)/len(recs)
        cut=sum(1 for r in recs if r['finish']!='stop')
        print(f, len(recs), 'acc', round(acc,3), 'cut', cut)

